package io.knowledgebrain.gateway;
import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;
class NotificationRoutesTest {
 @Test void preferenceRoutesAreExactAndDoNotAllowBrowserSuppressionWrites(){String root="/api/spaces/01a10000-0000-7000-8000-000000000000";for(String path:new String[]{"/notification-preference","/notification-preference/revisions","/notification-suppressions"}){assertEquals("notification",GatewayRoute.select("GET",root+path).service());assertNull(GatewayRoute.select("POST",root+path));assertNull(GatewayRoute.select("DELETE",root+path));}assertEquals("notification",GatewayRoute.select("PUT",root+"/notification-preference").service());assertNull(GatewayRoute.select("PUT",root+"/notification-suppressions"));assertNull(GatewayRoute.select("GET",root+"/notification-preference/anything"));}
 @Test void onlyDeclaredDeliveryAndNotificationOperationsReachTheirSeparateOwners(){String id="01a10000-0000-7000-8000-000000000000",d="/api/spaces/"+id+"/reminders/"+id+"/deliveries",n="/api/spaces/"+id+"/notifications";for(String path:new String[]{d,d+"/"+id,d+"/"+id+"/revisions"})assertEquals("planning",GatewayRoute.select("GET",path).service());assertEquals("planning",GatewayRoute.select("POST",d).service());assertEquals("planning",GatewayRoute.select("DELETE",d+"/"+id).service());for(String path:new String[]{n,n+"/"+id,n+"/"+id+"/revisions"})assertEquals("notification",GatewayRoute.select("GET",path).service());for(String method:new String[]{"PUT","DELETE"})assertEquals("notification",GatewayRoute.select(method,n+"/"+id).service());assertNull(GatewayRoute.select("POST",n));assertNull(GatewayRoute.select("POST",d+"/"+id));assertNull(GatewayRoute.select("PUT",d+"/"+id));assertNull(GatewayRoute.select("GET","/internal/planning/dispatched-reminders"));assertNull(GatewayRoute.select("POST","/internal/space/notification-authorization"));}
}
